    if (shape === 'U') return Math.min((1 - c) / 2, 0.45);
    if (shape === 'plus') return 0.9 - c;
    if (shape === 'H') return (1 - c) / 2;
    if (shape === 'band') return 0.3;
    if (shape === 'crescent') return 0.35;
    if (shape === 'leaf' || shape === 'drop' || shape === 'tri' || shape === 'sector') return 0.7;
