    D.ops.forEach((o) => { const d = segDist(wx, wy, o.ax, o.ay, o.bx, o.by); if (d <= Math.max(tol, o.t / 2 + 0.04) && d < bd) { bd = d; best = 'o:' + o.id; } });
    if (best) return best;
    // 2) merdiven
